import { createRoot } from 'react-dom/client';
import { Toaster } from 'sonner';
import App from './App';
import './styles.css';

const root = createRoot(document.getElementById('root')!);
root.render(<><App /><Toaster richColors position="top-right" /></>);

:root { color-scheme: light; }
html, body, #root { height: 100%; }
body { margin: 0; background: #ffffff; color: #0a0a0a;
       font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
       -webkit-font-smoothing: antialiased; }

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { useMemo, useState } from 'react';
import { RotateCcw } from 'lucide-react';

type Mark = 'X' | 'O' | null;
const LINES = [
  [0,1,2], [3,4,5], [6,7,8],
  [0,3,6], [1,4,7], [2,5,8],
  [0,4,8], [2,4,6],
];

function winner(board: Mark[]): { mark: Mark; line: number[] } | null {
  for (const line of LINES) {
    const [a, b, c] = line;
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return { mark: board[a], line };
    }
  }
  return null;
}

export default function App() {
  const [board, setBoard] = useState<Mark[]>(() => Array(9).fill(null));
  const [turn, setTurn] = useState<'X' | 'O'>('X');
  const [scores, setScores] = useState({ X: 0, O: 0, draws: 0 });

  const result = winner(board);
  const isDraw = !result && board.every(Boolean);
  const finished = !!result || isDraw;

  function play(i: number) {
    if (finished || board[i]) return;
    const next = board.slice();
    next[i] = turn;
    setBoard(next);
    const w = winner(next);
    if (w?.mark) {
      setScores((s) => ({ ...s, [w.mark as 'X' | 'O']: s[w.mark as 'X' | 'O'] + 1 }));
    } else if (next.every(Boolean)) {
      setScores((s) => ({ ...s, draws: s.draws + 1 }));
    } else {
      setTurn(turn === 'X' ? 'O' : 'X');
    }
  }

  function reset() {
    setBoard(Array(9).fill(null));
    setTurn('X');
  }

  function newMatch() {
    reset();
    setScores({ X: 0, O: 0, draws: 0 });
  }

  const status = useMemo(() => {
    if (result?.mark) return `${result.mark} wins`;
    if (isDraw) return 'Draw';
    return `${turn} to play`;
  }, [result, isDraw, turn]);

  return (
    <div className="min-h-screen flex items-center justify-center bg-[#ffffff] p-4">
      <div className="w-full max-w-sm rounded-2xl bg-[#f7f7f7] p-6 ring-1 ring-[#eaeaea] shadow-2xl">
        <div className="flex items-center justify-between mb-4">
          <h1 className="text-lg font-semibold text-[#0a0a0a]">Tic Tac Toe</h1>
          <button
            onClick={newMatch}
            className="rounded-md bg-[#efefef] px-2 py-1 text-xs text-[#0a0a0a] hover:bg-[#e5e5e5] inline-flex items-center gap-1"
          ><RotateCcw className="h-3 w-3" /> New match</button>
        </div>

        <div className="grid grid-cols-3 gap-2 mb-4">
          {board.map((cell, i) => {
            const inLine = result?.line.includes(i);
            const isX = cell === 'X';
            const isO = cell === 'O';
            return (
              <button
                key={i}
                onClick={() => play(i)}
                disabled={!!cell || finished}
                aria-label={`Cell ${i + 1}`}
                className={[
                  'aspect-square rounded-xl text-5xl font-semibold transition select-none',
                  'bg-[#efefef] hover:bg-[#e5e5e5]',
                  'disabled:cursor-not-allowed',
                  inLine ? 'ring-2 ring-[#feeeb2]' : '',
                  isX ? 'text-[#76b900]' : isO ? 'text-[#feeeb2]' : 'text-[#0a0a0a]',
                ].join(' ')}
              >{cell ?? ''}</button>
            );
          })}
        </div>

        <div className="flex items-center justify-between text-sm">
          <span className="text-[#0a0a0a] font-medium">{status}</span>
          <button
            onClick={reset}
            disabled={!board.some(Boolean)}
            className="text-xs text-[#525252] hover:text-[#0a0a0a] disabled:opacity-40"
          >Reset board</button>
        </div>

        <div className="mt-4 grid grid-cols-3 gap-2 text-center text-xs">
          <div className="rounded-lg bg-[#efefef] py-2">
            <div className="text-[#76b900] font-semibold text-base">{scores.X}</div>
            <div className="text-[#525252]">X</div>
          </div>
          <div className="rounded-lg bg-[#efefef] py-2">
            <div className="text-[#0a0a0a] font-semibold text-base">{scores.draws}</div>
            <div className="text-[#525252]">Draws</div>
          </div>
          <div className="rounded-lg bg-[#efefef] py-2">
            <div className="text-[#feeeb2] font-semibold text-base">{scores.O}</div>
            <div className="text-[#525252]">O</div>
          </div>
        </div>
      </div>
    </div>
  );
}
